-- 23_huntsville_bios.sql
-- Huntsville candidate bios, drafted from candidates' own websites or, where
-- no website bio exists, from their published positions on SmarterVote
-- (Andreas's method, approved 2026-10-17). Bios are display text only;
-- no source is shown for bios in the published version.
-- Candidates with no draftable bio (Ellas, Renwick, Terziano, Lowe,
-- Schumacher, Legrand) are intentionally left NULL -> 'No bio on record.'

UPDATE candidates SET bio = 'Dan Armour is a lifelong Huntsville resident who has served 12 years on Council, including two terms representing Brunel Ward and several years as District Councillor and Deputy Mayor. He is running for mayor on a back-to-basics platform of listening to residents, communicating better, and being transparent about town finances.' WHERE name = 'Dan Armour';
UPDATE candidates SET bio = 'Dan Caswell is a Huntsville resident, married with a family, and a local business owner. He says his business experience taught him to manage a budget, solve real problems and make tough decisions, and he wants to bring that practical experience to Town Hall. He is running for mayor on putting Huntsville first: responsible spending, health-care readiness, better infrastructure and strong core services.' WHERE name = 'Dan Caswell';
UPDATE candidates SET bio = 'Rebecca Mello is the youngest candidate in the mayoral race. She is running to represent the voices of Huntsville residents and serve their best interests, with a stated focus on bringing younger and older generations together, protecting the town''s lakes, waterfront and outdoor-recreation heritage, and planning growth deliberately rather than letting it happen unplanned. She documents her campaign in day-counted posts on her own social accounts.' WHERE name = 'Rebecca Mello';
UPDATE candidates SET bio = 'Scott Morrison is a sitting town councillor in his first term, with a background in business leadership and public service. He created the town''s doctor recruitment incentive program, which he says has brought 9 new family doctors to Huntsville, and he voted against council pay raises. He is running for mayor on disciplined fiscal management, better roads and infrastructure, and transparent, accountable government.' WHERE name = 'Scott Morrison';
UPDATE candidates SET bio = 'Bob Stone was first elected to Council in 2014 and has served 12 years: two terms on Town Council and one on both Town and District Council. He is a business owner who has owned and operated three businesses, including Christmas Tyme on Main Street for 20 years. He also serves as a board member of the Simcoe Muskoka District Health Unit and chairs Huntsville''s Planning Council and its Active Transportation and Transit Committee.' WHERE name = 'Bob Stone';
UPDATE candidates SET bio = 'James Bowler is running for District and Town Councillor. In his own questionnaire answers, he says economic development should build careers, startups and families for people already in Huntsville, not just attract newcomers. His stated priority is spending accountability: showing taxpayers the value of money already spent before asking for more.' WHERE name = 'James Bowler';
UPDATE candidates SET bio = 'Leland “Lee” Maw is a fourth-generation Muskokan who has spent his entire life living and working in the community. He spent 15 years (1985–2000) in the municipal engineering department at the District of Muskoka, then built a career in construction, including nine years running his own Muskoka home inspection business and work as a facilities and project manager. He is running for council on protecting housing affordability, community engagement and infrastructure.' WHERE name = 'Leland Maw';
UPDATE candidates SET bio = 'Peggy Peterson is running for District and Town Councillor. In her own questionnaire answers, she calls for serious stormwater planning, enforcement of responsible development, and full leachate testing at the old tannery site.' WHERE name = 'Peggy Peterson';
UPDATE candidates SET bio = 'Geordie Sabbagh is running for Wards 1 & 2 councillor. He describes a councillor''s job as listening, finding the people who understand an issue, and bringing them to the table. His stated focus: neighbours-first decisions, responsible growth that fits Huntsville''s character, using every legal tool against persistent problem properties, and pressing for provincial and federal help on homelessness and addictions.' WHERE name = 'Geordie Sabbagh';
UPDATE candidates SET bio = 'Louisa Chiaramonte was raised in Kirkland Lake and spent ten years in Belize, where she ran a coffee shop and a 60-acre farm with an animal sanctuary and later served as treasurer of the SAGA Humane Society. She is the founder and CEO of the Huntsville agency AVI Media and has lived in Huntsville for three years. She says she filed the day before the nomination deadline to give voters a fresh voice with no pre-existing political ties.' WHERE name = 'Louisa Chiaramonte';
UPDATE candidates SET bio = 'Rylind Davis is a lifelong Huntsville resident who attended Saint Mary Catholic Elementary School and Saint Dominic Catholic Secondary School. He is studying History and Criminology at Lakehead University with the goal of becoming a high school teacher. He has served on the Huntsville and District of Muskoka Accessibility Advisory Committees, helps manage his family''s farm and bed and breakfast, and volunteers as a public speaker and mentor to youth in Ontario''s youth correctional centres.' WHERE name = 'Rylind Davis';
UPDATE candidates SET bio = 'Stephen Hernen is running for Wards 1 & 2 councillor. His stated positions, drawn from his own answers to a 2022 questionnaire, include moving tourism and marketing costs off the property tax base and onto the accommodation tax, starting to save now for the hospital redevelopment''s local share, zero-tolerance short-term-rental enforcement funded by higher licensing fees, and cutting the Town''s carbon footprint through building efficiencies.' WHERE name = 'Stephen Hernen';
UPDATE candidates SET bio = 'Jason FitzGerald is running for Wards 3, 4 & 5 councillor and has listed no campaign website or social accounts. In his own survey answers, he supports small agriculture and homesteading, and describes his family''s own climate actions — planting trees, a large vegetable garden, selling their gas-powered boat — alongside municipal ideas like electric fleet vehicles, expanded green bins and LEED-standard builds.' WHERE name = 'Jason FitzGerald';
UPDATE candidates SET bio = 'Tyler Ellis is a Huntsville resident, husband, father of four, and farmer living in Utterson. For more than a decade he has worked in community development and disability services, and he is a founding board member and treasurer of the Muskoka Community Land Trust. He is running for Wards 3, 4 & 5 councillor on better rural roads, responsible taxes, stronger rural services and evidence-based recreation planning.' WHERE name = 'Tyler Ellis';
UPDATE candidates SET bio = 'Kirsty Koop is running for the Brunel Ward council seat. Her stated approach is that local government starts with listening, and she wants to be an accessible councillor. Her priorities for Brunel include roads, bridges, snow removal, safe intersections and reliable cell service; more housing choices without losing character; and keeping lakes, forests and dark skies part of growth decisions.' WHERE name = 'Kirsty Koop';
UPDATE candidates SET bio = 'Michael Ankenmann describes himself as a professional engineer, wilderness guide and community leader running to serve Brunel Ward. His stated focus: holding the line on taxes after what he calls a nearly 30% increase over four years, making Town Hall fast and straightforward to deal with, and growing on the town''s own terms so Huntsville keeps its character.' WHERE name = 'Michael Ankenmann';
UPDATE candidates SET bio = 'Monty Clouthier is the sitting councillor for Ward 6 (Brunel), running for re-election. No campaign website is on file; he lists a Facebook page.' WHERE name = 'Monty Clouthier';
UPDATE candidates SET bio = 'Bruce Reain is the incumbent TLDSB trustee, running for re-election to represent Huntsville and Lake of Bays. No campaign website or social accounts are on file.' WHERE name = 'Bruce Reain';
UPDATE candidates SET bio = 'Elizabeth Purcell is a parent of a TLDSB student who decided to run after the before-and-after-school care program at her daughter''s school was cancelled. She describes a professional background in budget formulation, policy creation, legislation interpretation, public communication and program evaluation. She says trustees should be a visible, accessible bridge between families and the board, and be willing to publicly advocate to the province for adequate, sustainable funding.' WHERE name = 'Elizabeth Purcell';
UPDATE candidates SET bio = 'Joshua Boutotte is acclaimed as the Simcoe Muskoka Catholic District School Board trustee for Area 5; with only one candidate coming forward, no election is being held for the seat.' WHERE name = 'Joshua Boutotte';
UPDATE candidates SET bio = 'Bruce Cazabon is acclaimed as the French public school board (Conseil scolaire public du Nord-Est, Zone A) trustee; no election is being held for the seat.' WHERE name = 'Bruce Cazabon';
UPDATE candidates SET bio = 'Donald Blais is a telecommunications entrepreneur with 29 years in the field, specializing in fiber optics, married for 32 years and father of two. He has volunteered for 13 years with the Youth Justice Committee of York, Scarborough and Sault Ste. Marie, and says he has served 12 years as a school trustee in Simcoe Muskoka and Mississauga. His stated concerns: children''s well-being and safe schools, transparency, graduation rates, and support for children in difficulty.' WHERE name = 'Donald Blais';

-- Verify: expect 22
SELECT count(*) AS candidates_with_bio FROM candidates WHERE bio IS NOT NULL;
